{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C56"],
      "claim": "Molecule 1 has an absolute oral bioavailability of about 50% in healthy volunteers for the delayed-release tablet, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Molecule 2 has an absolute oral bioavailability of 68% (57–80%) in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Molecule 4 has an absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold and arguing against high bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred evidence molecules with direct absolute oral bioavailability measurements in ordinary conditions exceed 20%, including values around 50–96%; one direct negative value (18%) and some conflicting pediatric/metabolite records lower certainty but do not outweigh the positive evidence.",
  "evidence_gaps": [
    "Molecule 1 includes pediatric suspension estimates below 20% (16–16.5%) that conflict with adult healthy-volunteer estimates around 50%.",
    "Molecule 5 includes a pediatric estimate of 12% (C07), below threshold, while adult patient estimates are 22–55%.",
    "Molecule 10 records assess metabolite availability after prodrug administration rather than direct oral bioavailability, so they are not threshold-relevant for this endpoint."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

